//! 🧪️ Original text ordering matches the shared SQLite BINARY oracle within unchanged caller opportunities.
use semio_os_flow_host_source::ordering::{OriginalTextOrdering,FlowTextOrderingWork};
use semio_framework_job::{OriginalJobFixtureCaller,OriginalJobDecodeOwner,OriginalTurnFailure,StepContext,OperationId,Generation,close_original_retained_step};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,ValueRefusalKind};
use std::cmp::Ordering;
fn clock()->Option<u64>{Some(1000)}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(97146),Generation(17),RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:128*1024*1024,maximum_capacity_bytes:256*1024*1024,maximum_release_bytes:512*1024*1024,maximum_depth:4096},clock,1500,32768)}
fn native<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));result.unwrap()}
fn close(work:&mut FlowTextOrderingWork,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant){work.begin_close();for _ in 0..20{if work.terminal_is_empty(){break}native(caller,decoder,g,|cx|cx.with_original_retirement(|cx|{let d=work.close_demands();close_original_retained_step(cx,d,|grant|work.close_step(grant))?;Ok(())}));}assert!(work.terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(g.maximum_copy_bytes)?;decoder.close_on_source(cx)?;Ok(())})).unwrap();}}
fn pump(work:&mut FlowTextOrderingWork,left:&str,right:&str,cx:&mut StepContext<'_>)->Result<Option<Ordering>,OriginalTurnFailure>{for _ in 0..512{let before=(cx.retained_progress(),cx.fuel_remaining());if let Some(order)=work.step(left,right,cx)?{return Ok(Some(order))}if cx.should_yield()||cx.is_cancelled()||before==(cx.retained_progress(),cx.fuel_remaining()){break}}Ok(None)}
fn words(row:&serde_json::Value)->(String,String){if let Some(repeat)=row["repeat"].as_u64(){let prefix=row["prefix"].as_str().unwrap().repeat(repeat as usize);(prefix.clone()+row["leftSuffix"].as_str().unwrap(),prefix+row["rightSuffix"].as_str().unwrap())}else{(row["left"].as_str().unwrap().into(),row["right"].as_str().unwrap().into())}}
#[test]
fn original_text_order_matches_binary_oracle_with_one_item_cancel_and_200_calls(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("📁️cases.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let(left,right)=words(row);let expected=match row["expected"].as_str().unwrap(){"less"=>Ordering::Less,"greater"=>Ordering::Greater,_=>Ordering::Equal};assert_eq!(left.cmp(&right),expected);
  let mut raw=OriginalTextOrdering::new();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};let minimum=raw.next_demands(&left,&right,0).unwrap().copy_bytes;for denied in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:minimum-1,..g}]{let turn=raw.advance(&left,&right,denied);assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(raw.step_progress(),Default::default())}raw.begin_close();while !raw.terminal_is_empty(){raw.close_step(g).result.unwrap();}
  for(items,copy,calls)in[(1,4096,10000),(512,32768,200)]{let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:copy,..g};native(&mut caller,&mut decoder,g,|_|Ok(()));let mut work=FlowTextOrderingWork::new();let mut output=None;
   for turn in 0..calls{assert!(native(&mut caller,&mut decoder,RetainedCloneGrant{maximum_items:0,..g},|cx|pump(&mut work,&left,&right,cx)).is_none());assert_eq!(caller.receipt(),Default::default());output=native(&mut caller,&mut decoder,g,|cx|pump(&mut work,&left,&right,cx));if output.is_some(){break}assert!(turn+1<calls)}assert_eq!(output,Some(expected));close(&mut work,&mut caller,&mut decoder,g);caller.retire(g);
  }
 }
 let left="a".repeat(4096);let right=left.clone()+"b";for stop in [0,1,7,17,50]{let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};native(&mut caller,&mut decoder,g,|_|Ok(()));let mut work=FlowTextOrderingWork::new();for _ in 0..stop{native(&mut caller,&mut decoder,g,|cx|work.step(&left,&right,cx));}caller.cancel().cancel_now();assert!(native(&mut caller,&mut decoder,g,|cx|work.step(&left,&right,cx)).is_none());assert_eq!(caller.receipt(),Default::default());close(&mut work,&mut caller,&mut decoder,g);caller.retire(g);}
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:4096};native(&mut caller,&mut decoder,g,|_|Ok(()));let mut work=FlowTextOrderingWork::new();native(&mut caller,&mut decoder,g,|cx|work.step(&left,&right,cx));let other=left.clone();let error=native(&mut caller,&mut decoder,g,|cx|Ok(work.step(&other,&right,cx))).unwrap_err();assert_eq!(error.primary_value().unwrap().kind,ValueRefusalKind::InvariantViolated);close(&mut work,&mut caller,&mut decoder,g);caller.retire(g);
}
